import {setVrsText} from './branding.mjs';
const root=document.querySelector('[data-news-station]');
const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
const fallback={id:'club-welcome',kind:'club',label:'Noticias del club',title:'Todo lo que se mueve en el club',description:'Consulta el calendario, las piezas del mercadillo, los álbumes y el simulador.',href:'index.html#calendario',image:'assets/cabecera-coches-atardecer.jpg'};
let club=[],motor=[],mode='club',index=0,playing=!reduced,hover=false,loading=false,lastClubIds='',motorStale=false,motorRetryAt=0,clockOffset=0;
const $=s=>root.querySelector(s),list=()=>mode==='club'?(club.length?club:[fallback]):motor;
function safeLink(value){try{const url=new URL(value,location.href);if(url.origin===location.origin)return url.href;if(url.protocol==='https:'&&['www.diariomotor.com','diariomotor.com','www.motorpasion.com','motorpasion.com'].includes(url.hostname)&&!url.username&&!url.password)return url.href;}catch{}return new URL('index.html#noticias',location.href).href;}
function show(){const items=list(),item=items[index]||fallback;setVrsText($('[data-news-title]'),item.title);setVrsText($('[data-news-description]'),item.description);$('[data-news-label]').textContent=item.label;$('[data-news-screen-label]').textContent=mode==='motor'?'ACTUALIDAD DEL MOTOR':'CLUB OCTAVIA';setVrsText($('[data-news-screen-title]'),item.title);const link=$('[data-news-link]');link.href=safeLink(item.href);link.textContent=mode==='motor'?'Leer en '+item.source+' ↗':'Ver en el club ↗';const external=new URL(link.href).origin!==location.origin;if(external){link.target='_blank';link.rel='noopener noreferrer';}else{link.removeAttribute('target');link.removeAttribute('rel');}const image=$('[data-news-image]');image.src=/^(assets\/|\/api\/(market|gallery)\/photos\/)/.test(item.image||'')?item.image:fallback.image;image.dataset.contain=String(item.kind==='record');$('[data-news-origin]').textContent=item.published?'Publicado '+new Intl.DateTimeFormat('es-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Madrid'}).format(new Date(item.published))+(motorStale?' · Última lectura disponible':''):'';$('[data-news-counter]').textContent=(mode==='club'?'CLUB':'MOTOR')+' · '+(index+1)+' / '+Math.max(1,items.length);root.dataset.newsMode=mode;root.dataset.newsId=item.id;}
async function loadMotor(){if(Date.now()<motorRetryAt)return !!motor.length;try{const r=await fetch('/api/club/motor-news');if(!r.ok)throw Error();const data=await r.json();motor=Array.isArray(data.items)?data.items:[];motorStale=data.stale===true;return !!motor.length;}catch{motorRetryAt=Date.now()+60000;return false;}}
async function next(){if(loading)return;const items=list();if(mode==='club'&&index>=items.length-1){if(!motor.length){loading=true;const ok=await loadMotor();loading=false;if(!ok){$('[data-news-status]').textContent='Los titulares del motor no están disponibles ahora. Seguimos mostrando las noticias del club.';index=0;show();return;}}mode='motor';index=0;$('[data-news-status]').textContent='';}else index=(index+1)%Math.max(1,items.length);show();}
async function refreshClub(){try{const r=await fetch('/api/club/news',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();if(Number.isFinite(Date.parse(data.updatedAt)))clockOffset=Date.parse(data.updatedAt)-Date.now();const fresh=Array.isArray(data.items)?data.items:[],ids=fresh.map(i=>i.id).join('|'),selected=list()[index]?.id;let hadNew=false;if(lastClubIds&&ids!==lastClubIds){const oldIds=new Set(club.map(i=>i.id));if(fresh.some(i=>!oldIds.has(i.id))){mode='club';index=0;hadNew=true;}}club=fresh;lastClubIds=ids;if(mode==='club'){const found=club.findIndex(i=>i.id===selected);if(found>=0&&!hadNew)index=found;else index=Math.min(index,Math.max(0,club.length-1));}$('[data-news-status]').textContent='';show();}catch{$('[data-news-status]').textContent='No se han podido actualizar las novedades del club. Volveremos a intentarlo.';if(!club.length)show();}}
if(root){$('[data-news-image]').addEventListener('error',event=>{if(!event.target.src.endsWith(fallback.image))event.target.src=fallback.image;});$('[data-news-next]').addEventListener('click',()=>void next());$('[data-news-prev]').addEventListener('click',()=>{index=(index-1+list().length)%Math.max(1,list().length);show();});$('[data-news-club]').addEventListener('click',()=>{mode='club';index=0;show();});const play=$('[data-news-play]');function playState(){play.setAttribute('aria-pressed',String(playing));play.setAttribute('aria-label',playing?'Pausar noticias':'Reanudar noticias');play.textContent=playing?'Ⅱ':'▶︎';}playState();play.addEventListener('click',()=>{playing=!playing;playState();});root.addEventListener('mouseenter',()=>hover=true);root.addEventListener('mouseleave',()=>hover=false);setInterval(()=>{if(playing&&!hover&&!document.hidden&&!root.contains(document.activeElement))void next();},10000);setInterval(()=>{if(!document.hidden)void refreshClub();},60000);void refreshClub();void loadMotor();setInterval(async()=>{if(!document.hidden){await loadMotor();if(mode==='motor'){index=Math.min(index,Math.max(0,motor.length-1));show();}}},900000);}
const clock=document.querySelector('[data-clock-time]'),svgNS='http://www.w3.org/2000/svg';if(clock){const ticks=document.querySelector('[data-clock-ticks]');for(let i=0;i<=24;i++){const angle=(-135+i*270/24)*Math.PI/180,major=i%4===0,line=document.createElementNS(svgNS,'line');const point=r=>[120+Math.sin(angle)*r,120-Math.cos(angle)*r];const [x1,y1]=point(major?84:91),[x2,y2]=point(98);for(const [k,v]of Object.entries({x1,y1,x2,y2,stroke:major?'#e3edf3':'#6f8999','stroke-width':major?2:1}))line.setAttribute(k,v);ticks.append(line);if(major){const t=document.createElementNS(svgNS,'text'),[x,y]=point(72);for(const [k,v]of Object.entries({x,y:y+4,'text-anchor':'middle',fill:'#c4d7e4','font-size':11}))t.setAttribute(k,v);t.textContent=String(i).padStart(2,'0');ticks.append(t);}}const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),date=new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',weekday:'long',day:'numeric',month:'long',year:'numeric'});function tick(){const now=new Date(Date.now()+clockOffset),time=parts.format(now),[h,m,s]=time.split(':').map(Number);clock.textContent=time;clock.dateTime=now.toISOString();document.querySelector('[data-clock-date]').textContent=date.format(now);document.querySelector('[data-clock-needle]').style.setProperty('--clock-angle',(-135+(h+m/60+s/3600)*270/24)+'deg');}tick();setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();if(root)void refreshClub();}});window.addEventListener('focus',tick);}
export function weatherLabel(code){if(code===0)return 'Despejado';if(code<=3)return 'Nubosidad variable';if([45,48].includes(code))return 'Niebla';if(code>=95)return 'Tormenta';if(code>=71&&code<=77||code>=85&&code<=86)return 'Nieve';if(code>=51&&code<=67||code>=80&&code<=82)return 'Lluvia';return 'Tiempo variable';}
async function updateWeather(){try{const r=await fetch('/api/club/weather');if(!r.ok)throw Error();const w=await r.json();if(!Number.isFinite(w.temperature))throw Error();document.querySelector('[data-weather-value]').textContent=Math.round(w.temperature)+' °C · '+weatherLabel(w.code);document.querySelector('[data-weather-stamp]').textContent=w.location+' · '+(w.observedAt?.split('T')[1]||'');}catch{document.querySelector('[data-weather-value]').textContent='Tiempo no disponible';document.querySelector('[data-weather-stamp]').textContent='Barcelona';}}
if(document.querySelector('[data-weather-value]')){void updateWeather();setInterval(()=>{if(!document.hidden)void updateWeather();},600000);}
